// One measurement pass. Records the exact title, highlight and readback.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/probe_j1.mjs om-emu
import { mkdirSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { runZone } from './zone_session_j1.mjs';
import { applyStep, mainSteps, page28Steps } from './observe_j1.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/probe_j1.mjs om-emu\n');
  process.exit(2);
}
mkdirSync(resolve('work/out'), { recursive: true });
const lines = [];
const emit = (row) => {
  const text = JSON.stringify(row);
  lines.push(text);
  console.log(text);
};

async function session(name, candidate, lane, nvramPath) {
  const steps = (lane === 'page28' ? page28Steps() : mainSteps(candidate)).filter((s) => candidate || s.shared);
  const result = await runZone({
    checkout,
    outPath: 'work/out/probe-session-' + name + '.jsonl',
    tag: 'probe-' + name,
    candidate,
    help: true,
    rowLabel: true,
    page28: lane === 'page28',
    nvramPath,
    explanation: 'T3j measurement session ' + name + '. Same configuration as T3i. Role: behaviour where the session module says so.',
    change: candidate ? 'T3i final configuration' : 'none',
    async drive(ctx) {
      ctx.takeFaces();
      for (const step of steps) {
        const got = await applyStep(ctx, step);
        emit({
          session: name,
          candidate,
          lane,
          id: step.id,
          key: step.key || null,
          action: step.action || null,
          shared: step.shared,
          title: got.title,
          highlight: got.highlight,
          screen: got.screen,
          profile: got.profile,
          profileCached: got.profileCached,
          helpId: got.helpId,
          slotValue: got.slotValue,
          slotKind: got.slotKind,
          slotId: got.slotId,
          glyph: got.glyph,
          screenshot: got.screenshot,
          texts: got.texts,
          invariant: got.invariant,
          saves: got.saves ?? null,
          saveNames: got.saveNames ?? null,
          error: got.error,
        });
      }
    },
  });
  if (!result.ok) throw new Error(name + ' failed ' + result.failed);
}

try {
  await session('control', false, 'main', 'work/out/nvram-probe-control.json');
  await session('cprobe', true, 'main', 'work/out/nvram-probe-c1.json');
  await session('p28-control', false, 'page28', 'work/out/nvram-probe-p28-control.json');
  await session('p28-cprobe', true, 'page28', 'work/out/nvram-probe-p28-c1.json');
  emit({ step: 'done', ok: true });
} catch (e) {
  emit({ step: 'done', ok: false, error: String(e && e.stack ? e.stack : e) });
  process.exitCode = 1;
} finally {
  writeFileSync('work/out/probe-j1.jsonl', lines.join('\n') + (lines.length ? '\n' : ''));
}
